# LandScan Global 2024 population density classification.
# Official LandScan color scheme (yellow → orange → red → maroon gradient).
# Values represent estimated population count per ~1 km² pixel.
CLASS
    NAME "Unpopulated (0)"
    EXPRESSION ([pixel] = 0)
    STYLE
        COLOR 0 0 0
        OPACITY 0
    END
END

CLASS
    NAME "1 - 5"
    EXPRESSION ([pixel] >= 1 AND [pixel] <= 5)
    STYLE
        COLOR 255 255 190
        OPACITY 90
    END
END

CLASS
    NAME "6 - 25"
    EXPRESSION ([pixel] >= 6 AND [pixel] <= 25)
    STYLE
        COLOR 255 255 115
        OPACITY 90
    END
END

CLASS
    NAME "26 - 50"
    EXPRESSION ([pixel] >= 26 AND [pixel] <= 50)
    STYLE
        COLOR 255 255 0
        OPACITY 90
    END
END

CLASS
    NAME "51 - 100"
    EXPRESSION ([pixel] >= 51 AND [pixel] <= 100)
    STYLE
        COLOR 255 170 0
        OPACITY 90
    END
END

CLASS
    NAME "101 - 500"
    EXPRESSION ([pixel] >= 101 AND [pixel] <= 500)
    STYLE
        COLOR 255 102 0
        OPACITY 90
    END
END

CLASS
    NAME "501 - 2500"
    EXPRESSION ([pixel] >= 501 AND [pixel] <= 2500)
    STYLE
        COLOR 255 0 0
        OPACITY 90
    END
END

CLASS
    NAME "2501 - 5000"
    EXPRESSION ([pixel] >= 2501 AND [pixel] <= 5000)
    STYLE
        COLOR 204 0 0
        OPACITY 90
    END
END

CLASS
    NAME "5001+"
    EXPRESSION ([pixel] > 5000)
    STYLE
        COLOR 115 0 0
        OPACITY 90
    END
END
